urlset:
{{ base }}{{ url_for('blog.index') }}
{%- for a in articles %}
{{ base }}{{ url_for('blog.article', slug=a.slug) }}{{ a.updated_at[:10] }}
{%- endfor %}
{%- for p in pages %}
{{ base }}{{ url_for('blog.page', slug=p.slug) }}
{%- endfor %}
{%- for t in sidebar_tags %}
{{ base }}{{ url_for('blog.tag', slug=t.slug) }}
{%- endfor %}
